### Yechim va Konfiguratsiya:
```yaml
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_security_group" "web_sg" {
  name        = "khorazmiy-web-sg"
  description = "SSH va HTTP ruxsati"

  ingress {
    description = "SSH kirish"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["195.158.0.0/16"] # Faqat kompaniya ofis IP diapazoni
  }

  ingress {
    description = "Ommaviy HTTP"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "web_server" {
  ami           = "ami-0c7217cdde317cfec" # Ubuntu 22.04 LTS
  instance_type = "t3.medium"
  vpc_security_group_ids = [aws_security_group.web_sg.id]

  tags = {
    Name        = "Khorazmiy-Production-Server"
    Environment = "Prod"
  }
}

output "server_public_ip" {
  value       = aws_instance.web_server.public_ip
  description = "Yaratilgan serverning ommaviy IP manzili"
}
```

### Muhandislik tushuntirishi:
1. Infratuzilma kod sifatida (IaC) e'lon qilinadi, bu takrorlanuvchanlik va versiya nazoratini beradi.
2. SSH porti faqat xavfsiz ofis tarmog'iga cheklangan (0.0.0.0/0 qilinmagan), bu buzilishdan himoyalaydi.
3. Output orqali server tayyor bo'lgach IP darhol konsolda ko'rinadi.

### Ishga tushirish va tekshirish:
```bash
terraform init
terraform plan
terraform apply -auto-approve
```
